"use client"

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ComponentPropsWithoutRef,
} from "react"

import { cn } from "@workspace/ui/lib/utils"

export type CalculationOperation =
  | "sum"
  | "average"
  | "min"
  | "max"
  | "count"
  | "add"
  | "subtract"
  | "multiply"
  | "divide"
  | "percentage"
  | "percentage-change"
  | "remainder"
  | "power"
  | "sqrt"
  | "absolute"
  | "round"
  | "floor"
  | "ceil"
  | "factorial"
  | "gcd"
  | "lcm"

type SizeVariant = "sm" | "md" | "lg" | "xl" | "2xl"
type ColorVariant =
  | "default"
  | "primary"
  | "secondary"
  | "success"
  | "warning"
  | "error"

interface CalculationResultConfig {
  prefix?: string
  suffix?: string
  separator?: string
  currency?: string
  locale?: string
  decimalPlaces?: number
  animate?: boolean
  animationDuration?: number
}

export interface AdvancedCalculationProps
  extends Omit<ComponentPropsWithoutRef<"div">, "onChange"> {
  initialOperation?: CalculationOperation
  initialInput?: string | number[]
  resultConfig?: CalculationResultConfig
  size?: SizeVariant
  color?: ColorVariant
  showOperationsList?: boolean
  showInputBox?: boolean
  onCalculate?: (result: number, operation: CalculationOperation, values: number[]) => void
}

const sizeClasses: Record<SizeVariant, string> = {
  sm: "text-sm",
  md: "text-base",
  lg: "text-xl",
  xl: "text-3xl",
  "2xl": "text-5xl",
}

const colorClasses: Record<ColorVariant, string> = {
  default: "text-foreground",
  primary: "text-blue-600 dark:text-blue-400",
  secondary: "text-gray-600 dark:text-gray-400",
  success: "text-green-600 dark:text-green-400",
  warning: "text-yellow-600 dark:text-yellow-400",
  error: "text-red-600 dark:text-red-400",
}

const operationsList: { label: string; value: CalculationOperation }[] = [
  { label: "Sum", value: "sum" },
  { label: "Average", value: "average" },
  { label: "Minimum", value: "min" },
  { label: "Maximum", value: "max" },
  { label: "Count", value: "count" },
  { label: "Add", value: "add" },
  { label: "Subtract", value: "subtract" },
  { label: "Multiply", value: "multiply" },
  { label: "Divide", value: "divide" },
  { label: "Percentage", value: "percentage" },
  { label: "Percentage Change", value: "percentage-change" },
  { label: "Remainder", value: "remainder" },
  { label: "Power", value: "power" },
  { label: "Square Root", value: "sqrt" },
  { label: "Absolute", value: "absolute" },
  { label: "Round", value: "round" },
  { label: "Floor", value: "floor" },
  { label: "Ceiling", value: "ceil" },
  { label: "Factorial", value: "factorial" },
  { label: "GCD", value: "gcd" },
  { label: "LCM", value: "lcm" },
]

function computeGcd(a: number, b: number): number {
  let x = Math.abs(a)
  let y = Math.abs(b)
  while (y) {
    const temp = y
    y = x % y
    x = temp
  }
  return x
}

function computeFactorial(n: number): number {
  if (n < 0 || !Number.isInteger(n)) return NaN
  let result = 1
  for (let i = 2; i <= n; i++) {
    result *= i
  }
  return result
}

function executeCalculation(operation: CalculationOperation, values: number[]): number {
  const [a = 0, b = 0] = values

  switch (operation) {
    case "sum":
      return values.reduce((total, val) => total + val, 0)
    case "average":
      return values.length
        ? values.reduce((total, val) => total + val, 0) / values.length
        : 0
    case "min":
      return values.length ? Math.min(...values) : 0
    case "max":
      return values.length ? Math.max(...values) : 0
    case "count":
      return values.length
    case "add":
      return a + b
    case "subtract":
      return a - b
    case "multiply":
      return a * b
    case "divide":
      return b === 0 ? NaN : a / b
    case "percentage":
      return (a * b) / 100
    case "percentage-change":
      return a === 0 ? NaN : ((b - a) / a) * 100
    case "remainder":
      return b === 0 ? NaN : a % b
    case "power":
      return Math.pow(a, b)
    case "sqrt":
      return Math.sqrt(a)
    case "absolute":
      return Math.abs(a)
    case "round":
      return Math.round(a)
    case "floor":
      return Math.floor(a)
    case "ceil":
      return Math.ceil(a)
    case "factorial":
      return computeFactorial(a)
    case "gcd":
      return computeGcd(a, b)
    case "lcm":
      return a && b ? Math.abs(a * b) / computeGcd(a, b) : 0
    default:
      return 0
  }
}

export function AdvancedCalculation({
  initialOperation = "sum",
  initialInput = "100, 200, 300",
  resultConfig = {
    prefix: "",
    suffix: "",
    separator: ",",
    locale: "en-US",
    decimalPlaces: 2,
    animate: true,
    animationDuration: 800,
  },
  size = "md",
  color = "default",
  showOperationsList = true,
  showInputBox = true,
  onCalculate,
  className,
  ...props
}: AdvancedCalculationProps) {
  const [operation, setOperation] = useState<CalculationOperation>(initialOperation)
  const [inputString, setInputString] = useState<string>(
    Array.isArray(initialInput) ? initialInput.join(", ") : initialInput
  )

  const parsedValues = useMemo(() => {
    return inputString
      .split(",")
      .map((val) => Number(val.trim()))
      .filter((val) => !Number.isNaN(val))
  }, [inputString])

  const rawResult = useMemo(() => {
    return executeCalculation(operation, parsedValues)
  }, [operation, parsedValues])

  const [displayValue, setDisplayValue] = useState<number>(rawResult)
  const previousResultRef = useRef<number>(rawResult)

  useEffect(() => {
    if (!resultConfig.animate) {
      setDisplayValue(rawResult)
      previousResultRef.current = rawResult
      onCalculate?.(rawResult, operation, parsedValues)
      return
    }

    let startTime: number | null = null
    const startVal = previousResultRef.current
    const endVal = Number.isNaN(rawResult) || !Number.isFinite(rawResult) ? 0 : rawResult
    const diff = endVal - startVal
    const duration = resultConfig.animationDuration ?? 800

    const step = (timestamp: number) => {
      if (!startTime) startTime = timestamp
      const progress = Math.min((timestamp - startTime) / duration, 1)
      const current = startVal + diff * progress

      setDisplayValue(current)

      if (progress < 1) {
        requestAnimationFrame(step)
      } else {
        previousResultRef.current = endVal
        setDisplayValue(endVal)
      }
    }

    requestAnimationFrame(step)
    onCalculate?.(rawResult, operation, parsedValues)
  }, [rawResult, operation, parsedValues, resultConfig.animate, resultConfig.animationDuration, onCalculate])

  const formatResultValue = useCallback(
    (num: number): string => {
      if (Number.isNaN(rawResult) || !Number.isFinite(rawResult)) {
        return "Invalid calculation"
      }

      const decimals = resultConfig.decimalPlaces ?? 2
      let formatted: string

      if (resultConfig.currency) {
        formatted = new Intl.NumberFormat(resultConfig.locale ?? "en-US", {
          style: "currency",
          currency: resultConfig.currency,
          minimumFractionDigits: decimals,
          maximumFractionDigits: decimals,
        }).format(num)
      } else {
        formatted = new Intl.NumberFormat(resultConfig.locale ?? "en-US", {
          minimumFractionDigits: decimals,
          maximumFractionDigits: decimals,
        }).format(num)

        if (resultConfig.separator && resultConfig.separator !== ",") {
          formatted = formatted.replace(/,/g, resultConfig.separator)
        }
      }

      return `${resultConfig.prefix ?? ""}${formatted}${resultConfig.suffix ?? ""}`
    },
    [rawResult, resultConfig]
  )

  const containerClassName = cn(
    "w-full rounded-xl border bg-background p-6 shadow-sm transition-all",
    className
  )

  const valueDisplayClassName = cn(
    "inline-block font-mono tracking-wider tabular-nums transition-all font-bold",
    sizeClasses[size],
    colorClasses[color]
  )

  return (
    <div className={containerClassName} {...props}>
      <div className="space-y-1">
        <h3 className="text-lg font-semibold tracking-tight">Calculation Engine</h3>
        <p className="text-xs text-muted-foreground">
          Real-time reactive calculation with customizable animations and localization formats.
        </p>
      </div>

      {showOperationsList && (
        <div className="mt-4 flex flex-wrap gap-1.5">
          {operationsList.map((item) => (
            <button
              key={item.value}
              type="button"
              onClick={() => setOperation(item.value)}
              className={cn(
                "rounded-md border px-2.5 py-1 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
                operation === item.value
                  ? "bg-primary text-primary-foreground shadow"
                  : "hover:bg-accent hover:text-accent-foreground"
              )}
            >
              {item.label}
            </button>
          ))}
        </div>
      )}

      {showInputBox && (
        <div className="mt-4 space-y-1.5">
          <div className="flex items-center justify-between">
            <label className="text-xs font-medium text-muted-foreground">Dataset Inputs</label>
            <span className="text-[10px] text-muted-foreground font-mono">
              Count: {parsedValues.length}
            </span>
          </div>
          <input
            type="text"
            value={inputString}
            onChange={(e) => setInputString(e.target.value)}
            placeholder="e.g. 100, 200, 300"
            className="flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-sm transition-colors placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
          />
        </div>
      )}

      <div className="mt-4 rounded-lg bg-muted/40 p-4 border flex items-center justify-between">
        <div>
          <span className="text-xs text-muted-foreground block uppercase tracking-wider font-medium">
            Active Operation: {operation}
          </span>
          <div className="mt-1">
            <span className={valueDisplayClassName}>
              {formatResultValue(displayValue)}
            </span>
          </div>
        </div>
      </div>
    </div>
  )
}
